    {"code": "so", "zh": "索马里", "en": "Somalia", "continent": "非洲", "capital": "摩加迪沙", "area": "约63.8万平方公里", "population": "约1800万（2024年估算）", "language": "索马里语", "currency": "索马里先令（SOS）", "resources": ["畜牧业", "渔业", "乳香与没药"], "tourism": ["拉斯格尔岩画：非洲之角保存最好的史前岩画", "摩加迪沙海岸：印度洋畔的白色沙滩"], "intro": "索马里位于非洲之角最东端，拥有非洲大陆最长的海岸线之一。古代曾与阿拉伯和波斯世界贸易往来密切，乳香和没药闻名一时。1991年内战爆发后长期动荡，经济以游牧业和渔业为主。尽管局势不稳，其独特的地理位置与海洋资源仍具巨大潜力。"},

    {"code": "ke", "zh": "肯尼亚", "en": "Kenya", "continent": "非洲", "capital": "内罗毕", "area": "约58万平方公里", "population": "约5500万（2024年估算）", "language": "斯瓦希里语、英语", "currency": "肯尼亚先令（KES）", "resources": ["茶叶", "咖啡", "花卉", "野生动物旅游"], "tourism": ["马赛马拉国家保护区：角马大迁徙的核心舞台", "安博塞利国家公园：以乞力马扎罗雪山为背景的大象群", "蒙巴萨：印度洋畔的斯瓦希里风情海港"], "intro": "肯尼亚位于东非，横跨赤道，东临印度洋，是东非经济与交通枢纽。人类祖先化石在此多有发现，被称为“人类的摇篮”。茶叶与花卉出口居世界前列，旅游业是重要支柱。辽阔的稀树草原与野生动物大迁徙让肯尼亚成为非洲草原旅游的代名词。"},

    {"code": "ug", "zh": "乌干达", "en": "Uganda", "continent": "非洲", "capital": "坎帕拉", "area": "约24.1万平方公里", "population": "约4900万（2024年估算）", "language": "英语、斯瓦希里语", "currency": "乌干达先令（UGX）", "resources": ["咖啡", "黄金", "铜"], "tourism": ["布温迪国家公园：山地大猩猩栖息地，世界自然遗产", "默奇森瀑布：尼罗河在峡谷中奔涌成瀑", "鲁文佐里山脉：赤道雪山，非洲最高山脉之一"], "intro": "乌干达位于东非内陆，横跨赤道，维多利亚湖占据其东南边境，有“非洲明珠”之称。1894年成为英国保护国，1962年独立。咖啡是主要出口商品，近年石油勘探取得进展。境内湖泊众多、雨林苍翠，山地大猩猩观赏是全球顶级生态旅游项目。"},

    {"code": "tz", "zh": "坦桑尼亚", "en": "Tanzania", "continent": "非洲", "capital": "多多马", "area": "约94.5万平方公里", "population": "约6700万（2024年估算）", "language": "斯瓦希里语、英语", "currency": "坦桑尼亚先令（TZS）", "resources": ["黄金", "坦桑石", "天然气", "钻石"], "tourism": ["乞力马扎罗山：非洲最高峰，赤道上的雪山", "塞伦盖蒂国家公园：动物大迁徙的广阔草原", "桑给巴尔岛：香料群岛与石头城"], "intro": "坦桑尼亚位于东非，国土辽阔，乞力马扎罗山矗立其北部，海拔5895米，是非洲最高峰。1964年坦噶尼喀与桑给巴尔合并成立联合共和国，法定首都为多多马，最大城市是达累斯萨拉姆。黄金与天然气是重要矿藏，旅游业尤为发达。塞伦盖蒂的大迁徙与桑给巴尔的阿拉伯风情使其成为东非最著名的旅游地之一。"},

    {"code": "rw", "zh": "卢旺达", "en": "Rwanda", "continent": "非洲", "capital": "基加利", "area": "约2.6万平方公里", "population": "约1400万（2024年估算）", "language": "基尼亚卢旺达语、英语、法语", "currency": "卢旺达法郎（RWF）", "resources": ["锡", "钽", "钨", "咖啡"], "tourism": ["火山国家公园：追踪山地大猩猩的著名地点", "基加利大屠杀纪念中心：铭记1994年历史的场所"], "intro": "卢旺达位于东非内陆，号称“千丘之国”，山丘起伏、人口密度居非洲前列。1994年曾发生震惊世界的大屠杀，此后国家在重建中实现经济社会较快发展。咖啡出口和矿业是经济重要部分，基加利以整洁安全著称。山地大猩猩观光已成为该国高端旅游名片。"},

    {"code": "bi", "zh": "布隆迪", "en": "Burundi", "continent": "非洲", "capital": "基特加", "area": "约2.8万平方公里", "population": "约1300万（2024年估算）", "language": "基隆迪语、法语", "currency": "布隆迪法郎（BIF）", "resources": ["锡", "黄金", "咖啡"], "tourism": ["坦噶尼喀湖：非洲最深的湖泊之一，湖畔沙滩风光", "基比拉国家公园：云雾森林与黑猩猩栖息地"], "intro": "布隆迪位于东非内陆，与卢旺达同属大湖地区，境内多山，坦噶尼喀湖沿其西南边境延伸。1885年沦为德国殖民地，后由比利时托管，1962年独立。农业以咖啡和茶叶为主，矿业以锡矿见长。该国经济基础薄弱，是世界上最不发达国家之一。"},

    {"code": "cd", "zh": "刚果（金）", "en": "DR Congo", "continent": "非洲", "capital": "金沙萨", "area": "约234.5万平方公里", "population": "约1.02亿（2024年估算）", "language": "法语", "currency": "刚果法郎（CDF）", "resources": ["钴", "铜", "钻石", "黄金"], "tourism": ["维龙加国家公园：山地大猩猩与活火山并存的世界遗产", "刚果河：流量与长度居世界前列的大河"], "intro": "刚果民主共和国（刚果（金））位于非洲中部，是非洲面积第二大国，也是非洲人口最多的法语国家。19世纪末沦为比利时国王私人领地，后为比属刚果，1960年独立。境内矿藏极为丰富，钴储量居世界首位，铜、钻石、黄金储量可观。绵延的刚果雨林是仅次于亚马孙的世界第二大热带雨林。"},

    {"code": "cg", "zh": "刚果（布）", "en": "Republic of the Congo", "continent": "非洲", "capital": "布拉柴维尔", "area": "约34.2万平方公里", "population": "约600万（2024年估算）", "language": "法语", "currency": "中非法郎（XAF）", "resources": ["石油", "木材", "钾盐"], "tourism": ["奥扎拉国家公园：大象与西部低地大猩猩的家园", "刚果河：与金沙萨隔河相望的城市风光"], "intro": "刚果共和国（刚果（布））位于非洲中西部，横跨赤道，首都布拉柴维尔与刚果（金）首都金沙萨隔刚果河相望。1880年成为法国殖民地，1960年独立。石油出口是经济命脉，林业与农业亦占重要地位。境内大面积热带雨林覆盖，生态环境原始而多样。"},

    {"code": "ga", "zh": "加蓬", "en": "Gabon", "continent": "非洲", "capital": "利伯维尔", "area": "约26.8万平方公里", "population": "约240万（2024年估算）", "language": "法语", "currency": "中非法郎（XAF）", "resources": ["石油", "锰", "木材", "铀"], "tourism": ["洛佩国家公园：河流蜿蜒的原始雨林", "卢安戈国家公园：观赏座头鲸与海滩大象的胜地"], "intro": "加蓬位于非洲中西部，横跨赤道，濒临大西洋，森林覆盖率超过85%。1839年起逐渐沦为法国殖民地，1960年独立。石油、锰矿与木材出口构成经济支柱，人均收入居非洲前列。该国将大片国土辟为国家公园，是生态保护与高端旅游并重的典范。"},

    {"code": "cm", "zh": "喀麦隆", "en": "Cameroon", "continent": "非洲", "capital": "雅温得", "area": "约47.5万平方公里", "population": "约2800万（2024年估算）", "language": "法语、英语", "currency": "中非法郎（XAF）", "resources": ["石油", "铝土矿", "可可", "咖啡"], "tourism": ["喀麦隆火山：西非最高峰，海拔约4070米", "林贝黑沙滩：火山灰形成的独特黑沙滩", "瓦扎国家公园：萨赫勒地区的大象栖息地"], "intro": "喀麦隆位于非洲中西部，素有“非洲缩影”之称，从热带雨林到萨赫勒草原景观俱全。1884年成为德国殖民地，一战后被法、英瓜分，1960年法语区独立，次年英语区并入。石油、可可与铝土矿是重要资源。喀麦隆火山是西非最高峰，海拔约4070米。"},

    {"code": "cf", "zh": "中非共和国", "en": "Central African Republic", "continent": "非洲", "capital": "班吉", "area": "约62.3万平方公里", "population": "约550万（2024年估算）", "language": "法语、桑戈语", "currency": "中非法郎（XAF）", "resources": ["钻石", "黄金", "木材"], "tourism": ["班吉：乌班吉河畔的河港首都", "马诺沃贡达圣弗洛里斯国家公园：热带草原与瀑布"], "intro": "中非共和国位于非洲大陆正中的内陆，国名即源于此，1960年从法国独立。乌班吉河沿南部边境流过，北部为稀树草原。钻石与黄金开采是重要产业，但长期政局不稳制约发展。该国自然景观原始，野生动物资源丰富，却因安全形势少有游客踏足。"},

    {"code": "gq", "zh": "赤道几内亚", "en": "Equatorial Guinea", "continent": "非洲", "capital": "马拉博", "area": "约2.8万平方公里", "population": "约170万（2024年估算）", "language": "西班牙语、法语、葡萄牙语", "currency": "中非法郎（XAF）", "resources": ["石油", "天然气", "木材"], "tourism": ["马拉博：比奥科岛上的首都，火山岛风光", "比奥科岛：赤道雨林与火山景观"], "intro": "赤道几内亚位于非洲中西部，由大陆部分的木尼河地区和比奥科等岛屿组成，是非洲唯一以西班牙语为官方语言的国家。1778年起受西班牙殖民统治，1968年独立。上世纪90年代发现近海石油后经济快速增长，石油出口占其收入绝大部分。首都马拉博位于比奥科火山岛上。"},

    {"code": "st", "zh": "圣多美和普林西比", "en": "São Tomé and Príncipe", "continent": "非洲", "capital": "圣多美", "area": "约1000平方公里", "population": "约22万（2024年估算）", "language": "葡萄牙语", "currency": "多布拉（STN）", "resources": ["可可", "咖啡", "渔业"], "tourism": ["奥博国家公园：覆盖圣多美岛大部分的热带雨林", "圣多美岛海岸：火山岛的海滩与山峦"], "intro": "圣多美和普林西比是几内亚湾中的岛国，由圣多美、普林西比两个火山岛及周边小岛组成，是非洲面积最小的国家之一。1470年代葡萄牙人登陆并建立种植园，1975年独立，是非洲最早以葡萄牙语为官方语言的国家之一。可可曾是经济命脉，旅游业与近海石油勘探是新的希望。赤道雨林与殖民建筑构成独特海岛风情。"},

    {"code": "ng", "zh": "尼日利亚", "en": "Nigeria", "continent": "非洲", "capital": "阿布贾", "area": "约92.4万平方公里", "population": "约2.2亿（2024年估算）", "language": "英语", "currency": "奈拉（NGN）", "resources": ["石油", "天然气", "可可", "锡"], "tourism": ["祖玛岩：阿布贾附近的地标性巨型岩石", "奥孙-奥索博神树林：世界遗产中的圣林", "拉各斯：西非最大城市之一，活力海滩与市集"], "intro": "尼日利亚位于西非几内亚湾北岸，是非洲人口最多的国家，也是非洲最大经济体之一。1914年英国合并南北保护地，1960年独立。石油与天然气出口占财政收入绝大部分，奈莱坞电影业与流行音乐影响力遍及非洲。尼日尔河与贝努埃河在境内交汇，南部热带雨林与北部萨赫勒草原景观迥异。"},

    {"code": "bj", "zh": "贝宁", "en": "Benin", "continent": "非洲", "capital": "波多诺伏", "area": "约11.5万平方公里", "population": "约1300万（2024年估算）", "language": "法语", "currency": "西非法郎（XOF）", "resources": ["棉花", "石油", "磷酸盐"], "tourism": ["阿波美王宫：达荷美王国的宫殿建筑群，世界遗产", "冈维埃水上村庄：非洲最大的湖上民居聚落"], "intro": "贝宁位于西非，南濒几内亚湾，历史上达荷美王国曾在此强盛一时，1894年被法国征服，1960年独立。棉花是主要出口农产品，伏都教（沃顿教）在此发源并流传至美洲。南部的冈维埃水上村庄被称为“非洲威尼斯”。该国文化传统深厚，音乐与宗教仪式独具魅力。"},

    {"code": "tg", "zh": "多哥", "en": "Togo", "continent": "非洲", "capital": "洛美", "area": "约5.7万平方公里", "population": "约900万（2024年估算）", "language": "法语", "currency": "西非法郎（XOF）", "resources": ["磷酸盐", "棉花", "可可"], "tourism": ["洛美：西非大集市与海滨大道", "阿克洛阿山：多哥人心中的圣山，可俯瞰全景"], "intro": "多哥位于西非，国土南北狭长，是非洲最窄的国家之一，最窄处仅约50公里。1884年成为德国殖民地“多哥兰”，一战后由法英分治，1960年法语区独立。磷酸盐曾是其重要矿藏，农业以棉花与可可为主。首都洛美设有西非重要港口和著名的大集市。"},

    {"code": "gh", "zh": "加纳", "en": "Ghana", "continent": "非洲", "capital": "阿克拉", "area": "约23.9万平方公里", "population": "约3400万（2024年估算）", "language": "英语", "currency": "加纳塞地（GHS）", "resources": ["黄金", "可可", "石油", "锰"], "tourism": ["埃尔米纳城堡：大西洋沿岸的殖民时期奴隶贸易城堡", "博苏姆推湖：陨石坑形成的圆形湖泊", "莫尔国家公园：西非著名的大象与野生动物栖息地"], "intro": "加纳位于西非几内亚湾北岸，因盛产黄金而被称为“黄金海岸”，1482年起成为欧洲殖民贸易据点。1957年独立，是撒哈拉以南非洲第一个摆脱殖民统治的国家。黄金、可可与石油是经济三大支柱，可可产量长期居世界前列。加纳政局稳定，被视作非洲民主治理的样板之一。"},

    {"code": "ci", "zh": "科特迪瓦", "en": "Côte d'Ivoire", "continent": "非洲", "capital": "亚穆苏克罗", "area": "约32.2万平方公里", "population": "约2900万（2024年估算）", "language": "法语", "currency": "西非法郎（XOF）", "resources": ["可可", "咖啡", "石油", "橡胶"], "tourism": ["亚穆苏克罗和平圣母大教堂：世界最大的教堂之一", "科莫埃国家公园：西非最大的保护区之一"], "intro": "科特迪瓦位于西非几内亚湾北岸，国名意为“象牙海岸”，历史上以象牙贸易闻名。1893年成为法国殖民地，1960年独立后长期是西非经济最发达的国家之一。可可产量多年居世界首位，咖啡与橡胶出口亦居前列。政治首都为亚穆苏克罗，经济中心阿比让是西非重要港口与金融城市。"},

    {"code": "lr", "zh": "利比里亚", "en": "Liberia", "continent": "非洲", "capital": "蒙罗维亚", "area": "约11.1万平方公里", "population": "约540万（2024年估算）", "language": "英语", "currency": "利比里亚元（LRD）", "resources": ["铁矿石", "橡胶", "木材", "黄金"], "tourism": ["蒙罗维亚：大西洋畔的椰林首都", "帕尔马斯角：非洲大陆最西端的岬角"], "intro": "利比里亚位于西非大西洋沿岸，1847年由美国遣返的自由黑人移民建立，是非洲最早获得独立的共和国。国名意为“自由之地”，首都蒙罗维亚以美国总统门罗命名。铁矿石与橡胶是传统经济支柱，两次内战使发展长期受挫。该国拥有西非大片原始雨林，自然景观保存完好。"},

    {"code": "sl", "zh": "塞拉利昂", "en": "Sierra Leone", "continent": "非洲", "capital": "弗里敦", "area": "约7.2万平方公里", "population": "约880万（2024年估算）", "language": "英语", "currency": "塞拉利昂利昂（SLL）", "resources": ["钻石", "铁矿石", "金", "铝土矿"], "tourism": ["弗里敦：西非最古老的大学城之一，历史氛围浓厚", "蒂瓦伊岛自然保护区：灵长类动物保护区"], "intro": "塞拉利昂位于西非大西洋沿岸，1787年起成为英国安置解放黑奴的殖民地，首都弗里敦意为“自由城”，1961年独立。钻石、铁矿石与金矿资源丰富，钻石开采曾与内战冲突交织。该国自然风光优美，雨林与海滩相映，近年正逐步恢复旅游业。"},

    {"code": "gn", "zh": "几内亚", "en": "Guinea", "continent": "非洲", "capital": "科纳克里", "area": "约24.6万平方公里", "population": "约1400万（2024年估算）", "language": "法语", "currency": "几内亚法郎（GNF）", "resources": ["铝土矿", "铁矿石", "黄金", "钻石"], "tourism": ["宁巴山自然保护区：西非生物多样性热点，世界遗产", "富塔贾隆高原：西非多条大河的发源地"], "intro": "几内亚位于西非大西洋沿岸，被称为“西非水塔”，尼日尔河、塞内加尔河等多条大河发源于此。1890年代沦为法国殖民地，1958年率先公投独立，是法语非洲最早独立的国家。铝土矿储量居世界前列，是几内亚经济的最大支柱。富塔贾隆高原与宁巴山的雨林景观独具特色。"},

    {"code": "gw", "zh": "几内亚比绍", "en": "Guinea-Bissau", "continent": "非洲", "capital": "比绍", "area": "约3.6万平方公里", "population": "约210万（2024年估算）", "language": "葡萄牙语", "currency": "西非法郎（XOF）", "resources": ["腰果", "渔业", "木材"], "tourism": ["比绍：濒临热巴河口的港口城市", "比热戈斯群岛：大西洋中的群岛，传统村落与海滩"], "intro": "几内亚比绍位于西非大西洋沿岸，曾是葡萄牙殖民地在非洲的重要据点，1973年单方面宣布独立，1974年获得葡萄牙承认。腰果是最大出口产品，渔业资源丰富。比热戈斯群岛保留着独特的群岛文化与传统祭祀习俗。该国政局多次更迭，是世界上最不发达国家之一。"},

    {"code": "cv", "zh": "佛得角", "en": "Cape Verde", "continent": "非洲", "capital": "普拉亚", "area": "约4033平方公里", "population": "约60万（2024年估算）", "language": "葡萄牙语", "currency": "佛得角埃斯库多（CVE）", "resources": ["旅游业", "渔业", "盐"], "tourism": ["萨尔岛：白沙海滩与水上运动胜地", "圣安唐岛：群山峭壁的徒步天堂", "普拉亚老城：大西洋岛上的克里奥尔风情"], "intro": "佛得角是位于西非外海大西洋中的火山岛国，由十余个岛屿组成，曾为葡萄牙殖民地，1975年独立。岛屿多山，土地贫瘠，经济长期依赖外援与侨汇，近年旅游业成为重要支柱。萨尔岛等地的白色沙滩吸引欧洲游客。克里奥尔音乐与海洋风光构成其独特气质。"},

    {"code": "ao", "zh": "安哥拉", "en": "Angola", "continent": "非洲", "capital": "罗安达", "area": "约124.7万平方公里", "population": "约3600万（2024年估算）", "language": "葡萄牙语", "currency": "宽扎（AOA）", "resources": ["石油", "钻石", "铁矿石"], "tourism": ["卡兰杜拉瀑布：宽扎河上的壮丽瀑布", "罗安达湾：大西洋畔的葡式老城风光"], "intro": "安哥拉位于非洲西南部，濒临大西洋，曾是葡萄牙最大、最富庶的殖民地之一，1975年独立。此后长达27年的内战严重破坏经济，2002年停战后重建提速。石油与钻石出口占其收入绝大部分，是撒哈拉以南非洲重要产油国。大西洋海岸线与葡式建筑交织出独特的西南非风情。"},

    {"code": "zm", "zh": "赞比亚", "en": "Zambia", "continent": "非洲", "capital": "卢萨卡", "area": "约75.3万平方公里", "population": "约2000万（2024年估算）", "language": "英语", "currency": "赞比亚克瓦查（ZMW）", "resources": ["铜", "钴", "祖母绿"], "tourism": ["维多利亚瀑布：世界三大瀑布之一，与津巴布韦共有", "南卢安瓜国家公园：观赏河马与大象的著名公园", "卡富埃国家公园：非洲面积最大的国家公园之一"], "intro": "赞比亚位于非洲中南部内陆，因铜矿资源丰富而被称为“铜带之国”。1888年起受英国殖民统治，1964年独立，国名取自赞比西河。铜矿开采是经济核心，钴与祖母绿储量亦居世界前列。维多利亚瀑布与众多国家公园使其成为南部非洲重要旅游目的地。"},

    {"code": "mw", "zh": "马拉维", "en": "Malawi", "continent": "非洲", "capital": "利隆圭", "area": "约11.8万平方公里", "population": "约2100万（2024年估算）", "language": "英语、奇契瓦语", "currency": "马拉维克瓦查（MWK）", "resources": ["烟草", "茶叶", "铀", "稀土"], "tourism": ["马拉维湖：非洲第三大湖，湖水清澈被称为“星湖”", "利翁代国家公园：马拉维最古老的国家公园"], "intro": "马拉维位于非洲东南部内陆，马拉维湖占据其东部边境，约占国土面积五分之一，湖水清澈、鱼类丰富。1891年沦为英国殖民地“尼亚萨兰”，1964年独立。烟草是最大出口商品，茶叶与糖亦占重要地位。该国被称为“非洲温暖之心”，民风淳朴友善。"},

    {"code": "mz", "zh": "莫桑比克", "en": "Mozambique", "continent": "非洲", "capital": "马普托", "area": "约79.9万平方公里", "population": "约3300万（2024年估算）", "language": "葡萄牙语", "currency": "莫桑比克梅蒂卡尔（MZN）", "resources": ["天然气", "煤炭", "铝", "钛"], "tourism": ["巴扎鲁托群岛：珊瑚礁与海龟栖息的海岛天堂", "戈龙戈萨国家公园：野生动物重生的著名保护区", "马普托：印度洋畔的葡式风情首都"], "intro": "莫桑比克位于非洲东南部，濒临印度洋，拥有约2500公里海岸线。16世纪起成为葡萄牙殖民地，1975年独立后经历近20年内战。近年北部发现大型天然气田，经济发展潜力巨大。沿海群岛与内地国家公园构成丰富旅游资源，马普托的葡式建筑别具风情。"},

    {"code": "zw", "zh": "津巴布韦", "en": "Zimbabwe", "continent": "非洲", "capital": "哈拉雷", "area": "约39万平方公里", "population": "约1600万（2024年估算）", "language": "英语、绍纳语", "currency": "津巴布韦元（ZWL）", "resources": ["铂", "铬", "黄金", "钻石"], "tourism": ["维多利亚瀑布：宽约1700米的“雷鸣之烟”", "大津巴布韦遗址：中世纪绍纳文明的石城遗迹", "万基国家公园：大象数量众多的著名保护区"], "intro": "津巴布韦位于非洲南部内陆，国名源自古代大津巴布韦石城遗址，该遗址是中世纪绍纳文明的代表。1888年起受英国殖民统治，1980年独立建国。铂、铬、黄金与钻石矿藏丰富。维多利亚瀑布（当地称“莫西奥图尼亚”）是世界最大瀑布之一，与多个国家公园共同构成旅游支柱。"},

    {"code": "bw", "zh": "博茨瓦纳", "en": "Botswana", "continent": "非洲", "capital": "哈博罗内", "area": "约58.2万平方公里", "population": "约260万（2024年估算）", "language": "英语、茨瓦纳语", "currency": "普拉（BWP）", "resources": ["钻石", "铜", "镍"], "tourism": ["奥卡万戈三角洲：内陆三角洲，非洲最壮观的湿地", "乔贝国家公园：大象密度居非洲前列", "卡拉哈里沙漠：广袤的红色沙原"], "intro": "博茨瓦纳位于非洲南部内陆，1966年独立时为最贫困国家之一，因钻石开采实现经济腾飞，人均收入居非洲前列。政局长期稳定，是非洲治理良好的典范。奥卡万戈三角洲是罕见的沙漠内陆三角洲，每年洪水期吸引大量野生动物。钻石、铜镍矿与旅游业并列为经济支柱。"},

    {"code": "na", "zh": "纳米比亚", "en": "Namibia", "continent": "非洲", "capital": "温得和克", "area": "约82.4万平方公里", "population": "约260万（2024年估算）", "language": "英语", "currency": "纳米比亚元（NAD）", "resources": ["铀", "钻石", "铅", "锌"], "tourism": ["纳米布沙漠：世界上最古老的沙漠之一", "索苏斯维莱：红沙丘与千年枯树的经典景观", "埃托沙国家公园：盐沼上的野生动物乐园"], "intro": "纳米比亚位于非洲西南部，濒临大西洋，是世界上人口密度最低的国家之一。1884年成为德国殖民地，一战后由南非托管，1990年独立。铀与钻石矿藏丰富，是世界重要铀生产国。纳米布沙漠与海岸相接，形成沙丘直入大海的奇景，旅游业发展迅速。"},

    {"code": "za", "zh": "南非", "en": "South Africa", "continent": "非洲", "capital": "比勒陀利亚（行政）、开普敦（立法）、布隆方丹（司法）", "area": "约122万平方公里", "population": "约6200万（2024年估算）", "language": "英语等11种官方语言", "currency": "南非兰特（ZAR）", "resources": ["黄金", "铂", "钻石", "铬"], "tourism": ["桌山：开普敦地标，平顶山俯瞰大西洋", "克鲁格国家公园：南非最大的野生动物保护区", "好望角：大西洋与印度洋交汇之处"], "intro": "南非位于非洲大陆最南端，是非洲最发达的经济体，拥有三首都：行政首都比勒陀利亚、立法首都开普敦、司法首都布隆方丹。历史上长期实行种族隔离制度，1994年曼德拉当选总统后走向种族和解。黄金、铂与钻石矿藏丰富，制造业与金融业发达。多样的自然景观与“彩虹之国”的多民族文化使其成为非洲旅游首选地之一。"},

    {"code": "ls", "zh": "莱索托", "en": "Lesotho", "continent": "非洲", "capital": "马塞卢", "area": "约3万平方公里", "population": "约230万（2024年估算）", "language": "塞索托语、英语", "currency": "洛蒂（LSL）", "resources": ["钻石", "水资源", "羊毛与马海毛"], "tourism": ["马洛蒂山脉：高原山地风光，非洲南部最高峰之一", "塞拉班泰：南部非洲最高点，海拔约3482米"], "intro": "莱索托位于非洲南部，是被南非完全包围的国中之国，全部国土海拔都在1000米以上，被称为“天空王国”。19世纪巴索托王国为抵御布尔人入侵依附英国，1966年独立。该国是非洲平均海拔最高的国家之一，钻石开采与水资源出口是重要收入。高原草甸与马背文化独具魅力。"},

    {"code": "sz", "zh": "斯威士兰", "en": "Eswatini", "continent": "非洲", "capital": "姆巴巴内", "area": "约1.7万平方公里", "population": "约120万（2024年估算）", "language": "斯瓦蒂语、英语", "currency": "里兰吉尼（SZL）", "resources": ["糖", "木材", "煤炭"], "tourism": ["姆卡亚自然保护区：斯威士兰最大的野生动物保护区", "恩格韦尼矿区：非洲已知最古老的矿山之一"], "intro": "斯威士兰位于非洲南部，是非洲大陆上面积最小的国家之一，1968年从英国独立，2018年更名为埃斯瓦蒂尼。该国是非洲少数仍实行绝对君主制的国家之一，传统文化保留完整。制糖业是经济支柱，木材与煤炭亦占重要地位。每年举办的芦苇节等王室庆典吸引众多游客。"},

    {"code": "mg", "zh": "马达加斯加", "en": "Madagascar", "continent": "非洲", "capital": "塔那那利佛", "area": "约58.7万平方公里", "population": "约3000万（2024年估算）", "language": "马达加斯加语、法语", "currency": "阿里亚里（MGA）", "resources": ["香草", "石墨", "镍", "钴"], "tourism": ["钦吉·德·贝马拉哈石林：石灰岩尖峰组成的石林奇观", "诺西贝岛：印度洋香草群岛的海滩度假地", "昂达西贝雨林：观赏狐猴的著名保护区"], "intro": "马达加斯加是印度洋上的世界第四大岛，约8800万年前与非洲大陆分离，生物演化独立，狐猴、猴面包树等九成以上物种为特有。1896年沦为法国殖民地，1960年独立。香草产量居世界首位，石墨与镍钴矿藏丰富。石林、雨林与猴面包树大道构成独一无二的自然景观。"},

    {"code": "km", "zh": "科摩罗", "en": "Comoros", "continent": "非洲", "capital": "莫罗尼", "area": "约1862平方公里", "population": "约86万（2024年估算）", "language": "科摩罗语、法语、阿拉伯语", "currency": "科摩罗法郎（KMF）", "resources": ["香草", "依兰依兰", "丁香"], "tourism": ["卡尔塔拉火山：大科摩罗岛上的活火山", "莫罗尼老城：印度洋小城的清真寺与集市"], "intro": "科摩罗位于非洲东南莫桑比克海峡北端的印度洋上，由大科摩罗等岛屿组成，是火山岛国。历史上先后受阿拉伯与法国影响，1975年独立。香草与依兰依兰油是其重要出口产品，其中依兰依兰产量居世界前列。岛上多山地火山，椰林环抱，被称为“香料群岛”。"},

    {"code": "mu", "zh": "毛里求斯", "en": "Mauritius", "continent": "非洲", "capital": "路易港", "area": "约2040平方公里", "population": "约130万（2024年估算）", "language": "英语、法语、克里奥尔语", "currency": "毛里求斯卢比（MUR）", "resources": ["旅游业", "金融服务业", "甘蔗"], "tourism": ["七色土：查马雷尔色彩斑斓的火山沙丘", "莫纳山：世界遗产，奴隶逃亡史的见证地", "鹿岛：碧海白沙的度假胜地"], "intro": "毛里求斯是印度洋中的火山岛国，位于非洲大陆东南约2000公里处，曾是荷兰、法国与英国相继统治的殖民地，1968年独立。该国从单一蔗糖经济成功转型，金融、旅游与制衣业发达，人均收入居非洲前列。多元族群与文化在此交融，被誉为“印度洋上的珍珠”。"},

    {"code": "sc", "zh": "塞舌尔", "en": "Seychelles", "continent": "非洲", "capital": "维多利亚", "area": "约455平方公里", "population": "约12万（2024年估算）", "language": "塞舌尔克里奥尔语、英语、法语", "currency": "塞舌尔卢比（SCR）", "resources": ["金枪鱼渔业", "旅游业", "海椰子"], "tourism": ["五月谷：海椰子原产地，世界遗产", "拉迪格岛：花岗岩海滩与悠闲岛居生活", "阿尔达布拉环礁：巨龟栖息的著名环礁"], "intro": "塞舌尔是印度洋西部的群岛国家，由115个岛屿组成，是非洲面积最小、人口最少的国家。18世纪法英殖民者相继到来，1976年独立。该国是非洲人均收入最高的国家之一，经济高度依赖高端旅游业。原始海滩、花岗岩奇石与巨龟使其成为世界顶级度假地。"},
